import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {useContext,useMemo as useIdentityMemo} from 'react';
import {EditorInteractionScope,useEditorBoundary} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useScopedControl,controlIdentity,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {timelineEditSignature} from '@/components/nyc-tron/ui/components/forge/timeline/timeline-identity';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {snapFrame} from '@/components/nyc-tron/ui/components/forge/timeline/edits';
import {useEffect,useRef} from "react";
import {Platform,Text,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {Button} from "@/components/nyc-tron/ui/components/Button";
import {TextField} from "@/components/nyc-tron/ui/components/TextField";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import {keyboardKey,type KeyEventLike} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {useLocalPointer} from "@/components/nyc-tron/ui/components/gestures/useLocalPointer";
import {formatTimecode,type FrameRate} from "@/components/nyc-tron/ui/components/forge/timebase";
import {framesToSeconds} from "@/components/nyc-tron/ui/components/forge/timeline/time";
import {adjacentMarker,moveMarker,resizeMarker,sortMarkers,type MarkerUpdate,type TimelineMarker} from "@/components/nyc-tron/ui/components/forge/timeline/markers";
import {frameToX,type TimelineViewport} from "@/components/nyc-tron/ui/components/forge/timeline/viewport";

/** Props for {@linkcode TimelineMarkers}. */
export interface TimelineMarkersProps extends Omit<ViewProps,"children">,ScopedControlProps {
  readonly markers:readonly TimelineMarker[];
  readonly colors?:readonly {id:string;label:string;value:string}[];
  readonly onColorChange?:(id:string,colorId:string|undefined)=>void;
  readonly snapFrames?:readonly number[];readonly snapThreshold?:number;
  readonly viewport:TimelineViewport;
  readonly rate:FrameRate;
  readonly durationFrames:number;
  /** Where Add marker puts one. */
  readonly playheadFrame:number;
  readonly selectedMarkerId?:string;
  readonly onSelect:(id:string|undefined)=>void;
  /** Add at the playhead (Splice `addMarker`). */
  readonly onAdd:(at:{frame:number;seconds:number})=>void;
  /** Once per drag release, key press, button or committed text field (Splice `updateMarker`). */
  readonly onUpdate:(id:string,update:MarkerUpdate)=>void;
  readonly onRemove:(id:string)=>void;
  /** Jump to a marker. */
  readonly onSeek:(frame:number)=>void;
  readonly dropFrame?:boolean;
  readonly disabled?:boolean;
  className?:string;
  unstyled?:boolean;
}

const NO_SELECT=(Platform.OS==="web"?{userSelect:"none",touchAction:"none"}:{}) as object;
const HIT=44;
const TAP_PX=4;

function Flag({m,color,snapFrames=[],snapThreshold=0,viewport,rate,durationFrames,selected,onSelect,onUpdate,onRemove,onSeek,dropFrame,disabled,styled}:{
  color?:string|undefined;snapFrames?:readonly number[]|undefined;snapThreshold?:number|undefined;m:TimelineMarker;viewport:TimelineViewport;rate:FrameRate;durationFrames:number;selected:boolean;
  onSelect:(id:string|undefined)=>void;onUpdate:TimelineMarkersProps["onUpdate"];onRemove:(id:string)=>void;onSeek:(f:number)=>void;
  dropFrame:boolean;disabled:boolean;styled:boolean;
}){
  const [preview,store]=useLocalStore(()=>undefined as number|undefined);
  const latest=useRef({m,viewport,rate,durationFrames,onUpdate,onSelect,disabled});
  latest.current={m,viewport,rate,durationFrames,onUpdate,onSelect,disabled};
  const s=useRef({x0:0,moved:false});
  const target=(dx:number)=>{const l=latest.current;return Math.round(snapFrame(l.m.frame+dx/l.viewport.pxPerFrame,snapFrames,snapThreshold).frame);};
  const handlers=useLocalPointer({
    disabled,
    onBegin:pt=>{s.current={x0:pt.x,moved:false};},
    onMove:pt=>{
      const dx=pt.x-s.current.x0;
      if(Math.abs(dx)>TAP_PX)s.current.moved=true;
      if(!s.current.moved)return;
      const l=latest.current;
      const u=moveMarker(l.m,target(dx),l.durationFrames,l.rate);
      store.set(u?.frame??l.m.frame);
    },
    onRelease:pt=>{
      const l=latest.current;
      store.set(undefined);
      if(l.disabled)return;
      if(!s.current.moved){l.onSelect(l.m.id);return;}
      const u=moveMarker(l.m,target(pt.x-s.current.x0),l.durationFrames,l.rate);
      if(u)l.onUpdate(l.m.id,u);
    },
    onCancel:()=>store.set(undefined),
  });
  useEffect(()=>()=>store.set(undefined),[store]);
  const frame=preview??m.frame;
  const x=frameToX(viewport,frame);
  const len=(m.durationFrames??0)*viewport.pxPerFrame;
  if(x+len<-HIT||x>viewport.widthPx+HIT)return null;
  const tc=formatTimecode(frame,rate,{dropFrame});
  const step=(d:number)=>{const u=moveMarker(m,m.frame+d,durationFrames,rate);if(u&&!disabled)onUpdate(m.id,u);};
  const onKeyDown=(event:KeyEventLike)=>{
    const key=keyboardKey(event);
    const second=Math.max(1,Math.round(rate.numerator/rate.denominator));
    if(key==="Escape"){store.set(undefined);return;}
    if(key==="ArrowLeft"||key==="ArrowRight")step(key==="ArrowLeft"?-1:1);
    else if(key==="PageUp"||key==="PageDown")step(key==="PageUp"?second:-second);
    else if(key==="Enter"){onSelect(m.id);onSeek(m.frame);}
    else if(key===" ")onSelect(selected?undefined:m.id);
    else if((key==="Delete"||key==="Backspace")&&!disabled)onRemove(m.id);
    else return;
    (event as {preventDefault?:()=>void}).preventDefault?.();
  };
  const ink=styled?(selected?"bg-focus":"bg-info"):"";
  return <>
    {len>0?<View pointerEvents="none" {...{className:joinClasses(styled&&(selected?"bg-focus/20 border-y border-focus":"bg-info/15 border-y border-info/60"))}}
      style={{position:"absolute",left:x,top:22,height:12,width:len}}/>:null}
    <View {...handlers}
      {...{onKeyDown,focusable:!disabled,className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
      accessible accessibilityRole="adjustable"
      accessibilityLabel={`Marker ${m.name}${m.durationFrames?", range":""}${selected?", selected":""}`}
      accessibilityHint="Drag or use arrow keys to move. Enter jumps to it. Delete removes it."
      aria-valuemin={0} aria-valuemax={durationFrames} aria-valuenow={frame} aria-valuetext={tc} aria-disabled={disabled}
      accessibilityState={{selected,disabled}}
      accessibilityActions={[{name:"increment",label:"Later"},{name:"decrement",label:"Earlier"},{name:"activate",label:"Jump to marker"},
        {name:"remove",label:"Remove marker"}]}
      onAccessibilityAction={e=>{
        const a=e.nativeEvent.actionName;
        if(a==="increment")step(1);else if(a==="decrement")step(-1);
        else if(a==="activate"){onSelect(m.id);onSeek(m.frame);}else if(a==="remove"&&!disabled)onRemove(m.id);
      }}
      style={{position:"absolute",left:x-HIT/2,top:0,width:HIT,height:HIT,alignItems:"center",...NO_SELECT}}>
      {/* A pennant on a staff. */}
      <View pointerEvents="none" style={{position:"absolute",left:HIT/2-1,top:6,width:2,height:32,...(color?{backgroundColor:color}:{})}} {...{className:ink}}/>
      <View pointerEvents="none" style={{position:"absolute",left:HIT/2+1,top:6,width:12,height:10,borderTopRightRadius:3,borderBottomRightRadius:3,...(color?{backgroundColor:color}:{})}} {...{className:ink}}/>
    </View>
  </>;
}

/**
 * Sequence markers (D-24): a 44pt row (place it above the ruler) with a flag
 * per marker and a band for range markers, plus Add marker at the playhead,
 * previous and next, and an editor for the selected marker (name, note,
 * length, jump, remove). Drag a flag or use the arrow keys to move it; each
 * release, key press or committed field is one update. Optional app-owned
 * color metadata uses the supplied palette and callback, separate from engine timing.
 */
export function TimelineMarkers({scope='TimelineMarkers',revision=0,...props}:TimelineMarkersProps){
 const parent=useContext(EditorInteractionScope),owner=JSON.stringify(controlIdentity(scope,revision));
 const boundary=useEditorBoundary([owner,parent,props.disabledReason,props.disabled,props.markers,props.viewport,props.durationFrames,props.rate,props.snapFrames,props.snapThreshold]);
 const guard=useScopedControl(boundary,props,props.disabledReason!==undefined||!!props.disabled);
 return <EditorInteractionScope.Provider value={boundary}><TimelineMarkersBody key={owner} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onAdd={(value)=>guard.run('onAdd',host=>host.onAdd(value))}
  onUpdate={(id,value)=>guard.run('onUpdate',host=>host.onUpdate(id,value))}
  onRemove={(id)=>guard.run('onRemove',host=>host.onRemove(id))}
  {...(props.onColorChange?{onColorChange:(id:Parameters<NonNullable<TimelineMarkersProps['onColorChange']>>[0],color:Parameters<NonNullable<TimelineMarkersProps['onColorChange']>>[1])=>guard.run('onColorChange',host=>host.onColorChange?.(id,color))}:{})}
  onSelect={(id)=>guard.current()?.onSelect(id)}
  onSeek={(value)=>guard.current()?.onSeek(value)}/></EditorInteractionScope.Provider>;
}
function TimelineMarkersBody({
 actionError=null,disabledReason,
  colors=[],onColorChange,snapFrames=[],snapThreshold=0,markers,viewport,rate,durationFrames,playheadFrame,selectedMarkerId,onSelect,onAdd,onUpdate,onRemove,onSeek,
  dropFrame=false,disabled=false,className,unstyled=false,testID,style,...rest
}:TimelineMarkersProps&{actionError?:string|null}){
  if(markers.length>10000||new Set(markers.map(m=>m.id)).size!==markers.length||markers.some(m=>!m.id.trim()||m.id.length>512||m.name.length>1024||(m.note?.length??0)>8192||!Number.isSafeInteger(m.frame)||m.frame<0||m.durationFrames!==undefined&&(!Number.isSafeInteger(m.durationFrames)||m.durationFrames<0))||colors.length>256||new Set(colors.map(c=>c.id)).size!==colors.length||colors.some(c=>!c.id.trim()||!c.label.trim()||!c.value.trim())||snapFrames.length>10000||snapFrames.some(n=>!Number.isSafeInteger(n)||n<0)||!Number.isFinite(snapThreshold)||snapThreshold<0)throw new RangeError("Invalid timeline markers");
  const styled=!unstyled;
  const id=(s:string)=>testID?{testID:testID+"-"+s}:{};
  const tc=(f:number)=>formatTimecode(Math.max(0,Math.round(f)),rate,{dropFrame});
  const selected=markers.find(m=>m.id===selectedMarkerId);
  const prev=adjacentMarker(markers,playheadFrame,-1),next=adjacentMarker(markers,playheadFrame,1);
  const go=(m:TimelineMarker|undefined)=>{if(m){onSelect(m.id);onSeek(m.frame);}};
  const second=Math.max(1,Math.round(rate.numerator/rate.denominator));
  const dirty=useRef({name:false,note:false});
  const [draft,store]=useLocalStore(()=>({id:"",name:"",note:""}));
  // The fields edit a draft of the selected marker; switching markers reloads it.
  useEffect(()=>{dirty.current={name:false,note:false};store.set({id:selected?.id??"",name:selected?.name??"",note:selected?.note??""});},[selected?.id,selected?.name,selected?.note,store]);
  const commitText=(field:"name"|"note")=>{
    if(!selected||disabled||store.get().id!==selected.id||!dirty.current[field])return;
    dirty.current[field]=false;
    const value=store.get()[field].trim();
    if(field==="name"&&!value){store.set(d=>({...d,name:selected.name}));return;}
    if(value===(selected[field]??""))return;
    onUpdate(selected.id,{frame:selected.frame,seconds:framesToSeconds(selected.frame,rate),[field]:value});
  };
  return <View {...rest} {...(testID?{testID}:{})} {...{className:joinClasses("gap-2",className)}} style={style}>
    <ErrorMessage message={actionError??undefined} unstyled={unstyled}/>
    <View style={{flexDirection:"row",flexWrap:"wrap",alignItems:"center",gap:8}}>
      <Button title="Add marker" variant="secondary" size="sm" disabled={disabled||durationFrames<0} {...id("add")}
        accessibilityHint={`Adds a marker at ${tc(playheadFrame)}`}
        onPress={()=>{const f=Math.min(durationFrames,Math.max(0,Math.round(playheadFrame)));onAdd({frame:f,seconds:framesToSeconds(f,rate)});}}/>
      <Button title="Previous" variant="ghost" size="sm" disabled={!prev} {...id("prev")}
        accessibilityLabel="Previous marker" accessibilityHint={prev?`Jump to ${prev.name}`:"No marker before the playhead"} onPress={()=>go(prev)}/>
      <Button title="Next" variant="ghost" size="sm" disabled={!next} {...id("next")}
        accessibilityLabel="Next marker" accessibilityHint={next?`Jump to ${next.name}`:"No marker after the playhead"} onPress={()=>go(next)}/>
      <Text {...{className:joinClasses(styled&&"text-text-muted text-xs")}}>
        {markers.length?`${markers.length} marker${markers.length===1?"":"s"}`:"No markers. Add one at the playhead."}
      </Text>
    </View>
    <View accessibilityRole="list" accessibilityLabel="Markers" {...{className:joinClasses(styled&&"bg-surface-sunken border-b border-border")}}
      style={{height:HIT,width:viewport.widthPx,overflow:"hidden",direction:"ltr"}}>
      {sortMarkers(markers).map(m=><Flag key={m.id} m={m} viewport={viewport} rate={rate} durationFrames={durationFrames}
        color={colors.find(c=>c.id===m.colorId)?.value} snapFrames={snapFrames} snapThreshold={snapThreshold} selected={m.id===selectedMarkerId} onSelect={onSelect} onUpdate={onUpdate} onRemove={onRemove} onSeek={onSeek}
        dropFrame={dropFrame} disabled={disabled} styled={styled}/>)}
    </View>
    {selected?<View {...id("editor")} {...{className:joinClasses(styled&&"rounded-card border border-border bg-surface-raised")}}
      style={{padding:12,gap:10}}>
      <View style={{flexDirection:"row",flexWrap:"wrap",gap:12}}>
        <TextField id={"marker-name-"+selected.id} maxLength={1024} label="Marker name" value={draft.name} editable={!disabled} style={{minWidth:160}}
          className="grow" onChangeText={name=>{dirty.current.name=true;store.set(d=>({...d,name}));}} onBlur={()=>commitText("name")} onSubmitEditing={()=>commitText("name")}
          onKeyPress={e=>{if(e.nativeEvent.key==="Escape"){dirty.current.name=false;store.set(d=>({...d,name:selected.name}));}}}/>
        <TextField id={"marker-note-"+selected.id} label="Note" value={draft.note} editable={!disabled} style={{minWidth:160}}
          className="grow" onChangeText={note=>{dirty.current.note=true;store.set(d=>({...d,note}));}} onBlur={()=>commitText("note")} onSubmitEditing={()=>commitText("note")}
          onKeyPress={e=>{if(e.nativeEvent.key==="Escape"){dirty.current.note=false;store.set(d=>({...d,note:selected.note??""}));}}}/>
      </View>
      {onColorChange?<Select label="Marker color" value={selected.colorId??""} options={[{value:"",label:"Default"},...colors.map(c=>({value:c.id,label:c.label}))]} disabled={disabled} unstyled={unstyled} onValueChange={color=>onColorChange(selected.id,color||undefined)}/>:null}
      <View style={{flexDirection:"row",flexWrap:"wrap",alignItems:"center",gap:8}}>
        <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{fontVariant:["tabular-nums"]}}>
          {selected.durationFrames?`${tc(selected.frame)} for ${tc(selected.durationFrames)}`:`At ${tc(selected.frame)}`}
        </Text>
        <Button title="Shorter" variant="secondary" size="sm" disabled={disabled||!selected.durationFrames} {...id("shorter")}
          accessibilityHint="One second shorter; at zero it becomes a point marker"
          onPress={()=>{const u=resizeMarker(selected,(selected.durationFrames??0)-second,durationFrames,rate);if(u)onUpdate(selected.id,u);}}/>
        <Button title="Longer" variant="secondary" size="sm" disabled={disabled||selected.frame+(selected.durationFrames??0)>=durationFrames} {...id("longer")}
          accessibilityHint="One second longer; a point marker becomes a range"
          onPress={()=>{const u=resizeMarker(selected,(selected.durationFrames??0)+second,durationFrames,rate);if(u)onUpdate(selected.id,u);}}/>
        <Button title="Jump to marker" variant="secondary" size="sm" {...id("jump")} onPress={()=>onSeek(selected.frame)}/>
        <Button title="Remove" variant="ghost" size="sm" disabled={disabled} {...id("remove")}
          accessibilityLabel={`Remove marker ${selected.name}`} onPress={()=>onRemove(selected.id)}/>
      </View>
    </View>:null}
  </View>;
}

import type {TimelineTrack} from '@/components/nyc-tron/ui/components/forge/timeline/edits';
/** Bounded geometry/permission identity; a playback clock tick is not an edit. */
export function timelineEditSignature(tracks:readonly TimelineTrack[]):string{
 if(tracks.length>1000)throw new RangeError('Too many timeline tracks');
 const trackIds=new Set<string>(),clipIds=new Set<string>();let count=0;
 for(const track of tracks){
  if(!track.id.trim()||track.id.length>512||trackIds.has(track.id)||track.label.length>1024||!['video','overlay','audio'].includes(track.kind))throw new RangeError('Invalid timeline track');trackIds.add(track.id);
  count+=track.clips.length;if(count>50000)throw new RangeError('Too many timeline clips');
  for(const clip of track.clips){
   if(!clip.id.trim()||clip.id.length>512||clipIds.has(clip.id)||!Number.isSafeInteger(clip.startFrame)||clip.startFrame<0||![clip.sourceIn,clip.sourceOut,clip.speed].every(Number.isFinite)||clip.sourceIn<0||clip.sourceOut<=clip.sourceIn||clip.speed<=0||clip.sourceDuration!==undefined&&(!Number.isFinite(clip.sourceDuration)||clip.sourceDuration<clip.sourceOut))throw new RangeError('Invalid timeline clip');clipIds.add(clip.id);
  }
 }
 return JSON.stringify(tracks.map(t=>[t.id,t.kind,t.locked,t.hidden,t.muted,t.solo,t.clips.map(c=>[c.id,c.startFrame,c.sourceIn,c.sourceOut,c.speed,c.sourceDuration])]));
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import type {GestureResponderEvent,PanResponderCallbacks} from "react-native";

/** A point in the responder view's own coordinates (0,0 is its top-left corner). */
export interface LocalPoint {
  readonly x:number;
  readonly y:number;
  /**
   * Touch or stylus force 0..1 when the platform reports one (iOS touches and
   * Apple Pencil, Android styluses). Absent for mice and for touch screens
   * that report no force.
   */
  readonly pressure?:number;
}
/**
 * Callbacks for {@linkcode localPointerConfig}. Unlike `DragTransport`, which reports
 * page coordinates, these report points inside the view, for controls that map a
 * position to a value (a color disc, a seek bar, a clip edge).
 */
export interface LocalPointerHandlers {
  readonly disabled?:boolean;
  onBegin(point:LocalPoint):void;
  onMove(point:LocalPoint):void;
  onRelease(point:LocalPoint):void;
  /** OS termination, or a second pointer when {@linkcode LocalPointerHandlers.onPinch} is absent. */
  onCancel():void;
  /**
   * Two-pointer pinch. `scale` is the current pointer distance over the distance when
   * the second pointer landed; `center` is their midpoint. Once a pinch starts, the
   * gesture ends with {@linkcode LocalPointerHandlers.onPinchEnd} instead of a release.
   */
  onPinch?(scale:number,center:LocalPoint):void;
  onPinchEnd?():void;
}

type Latest={readonly current:LocalPointerHandlers};

const withForce=(point:{x:number;y:number},force:number|undefined):LocalPoint=>
  typeof force==="number"&&Number.isFinite(force)&&force>0?{...point,pressure:Math.min(1,force)}:point;
type Touch={readonly pageX:number;readonly pageY:number};

/**
 * PanResponder callbacks that report view-local points. The grant point is
 * `locationX/Y`, which is relative to the touched view, so every child of the
 * responder view must set `pointerEvents="none"`. Later points add the page-space
 * travel to the grant point; `locationX` on a move would be measured from whatever
 * view the pointer is over.
 */
export function localPointerConfig(latest:Latest):PanResponderCallbacks{
  let origin={x:0,y:0,pageX:0,pageY:0};
  let pinch:{distance:number}|undefined;
  let live=false;
  const local=(pageX:number,pageY:number,force?:number):LocalPoint=>withForce({x:origin.x+pageX-origin.pageX,y:origin.y+pageY-origin.pageY},force);
  const touchesOf=(event:GestureResponderEvent):readonly Touch[]=>event.nativeEvent.touches??[];
  const end=()=>{live=false;pinch=undefined;};
  return {
    onStartShouldSetPanResponder:()=>!latest.current.disabled,
    onMoveShouldSetPanResponder:()=>!latest.current.disabled,
    onPanResponderGrant:event=>{
      const n=event.nativeEvent;
      origin={x:n.locationX,y:n.locationY,pageX:n.pageX,pageY:n.pageY};
      pinch=undefined;
      live=true;
      latest.current.onBegin(withForce({x:n.locationX,y:n.locationY},n.force));
    },
    onPanResponderMove:event=>{
      if(!live)return;
      const touches=touchesOf(event);
      if(touches.length>=2){
        const handlers=latest.current;
        if(!handlers.onPinch){end();handlers.onCancel();return;}
        const [a,b]=touches as [Touch,Touch];
        const distance=Math.hypot(b.pageX-a.pageX,b.pageY-a.pageY);
        if(!pinch){
          // The one-pointer gesture that started this is abandoned, not committed.
          handlers.onCancel();
          pinch={distance:Math.max(distance,1)};
        }
        handlers.onPinch(distance/pinch.distance,local((a.pageX+b.pageX)/2,(a.pageY+b.pageY)/2));
        return;
      }
      if(pinch)return;
      latest.current.onMove(local(event.nativeEvent.pageX,event.nativeEvent.pageY,event.nativeEvent.force));
    },
    onPanResponderRelease:event=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onRelease(local(event.nativeEvent.pageX,event.nativeEvent.pageY));
    },
    // A parent ScrollView must not take a granted drag; the OS still can.
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onCancel();
    },
    onShouldBlockNativeResponder:()=>true,
  };
}

import {useContext,useLayoutEffect,useMemo,useRef} from "react";
import {PanResponder,type GestureResponderEvent,type GestureResponderHandlers,type PanResponderGestureState,type PanResponderCallbacks} from "react-native";
import {localPointerConfig,type LocalPointerHandlers} from "@/components/nyc-tron/ui/components/gestures/local-pointer";
import {EditorInteractionScope} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';

/**
 * Responder handlers for one view, built once and fed the latest callbacks on
 * every event. Spread the result on the view that defines the local coordinate
 * space; see {@linkcode localPointerConfig} for the `pointerEvents` rule.
 */
export function useLocalPointer(handlers:LocalPointerHandlers):GestureResponderHandlers{
  const scope=useContext(EditorInteractionScope);
  const latest=useRef(handlers);
  useLayoutEffect(()=>{latest.current=handlers;});
  const owner=useRef<{active:boolean;blocked:boolean;last:[GestureResponderEvent,PanResponderGestureState]|null}>({active:false,blocked:false,last:null});
  const config=useMemo<PanResponderCallbacks>(()=>localPointerConfig(latest),[]);
  const cancel=()=>{const s=owner.current;owner.current={active:false,blocked:true,last:null};if(s.active&&s.last)config.onPanResponderTerminate?.(...s.last);};
  useLayoutEffect(()=>{if(scope!==null)cancel();return()=>{if(scope!==null)cancel();};},[scope]);
  return useMemo(()=>PanResponder.create({
    ...config,
    onStartShouldSetPanResponder:(...args)=>{owner.current.blocked=false;return config.onStartShouldSetPanResponder?.(...args)??false;},
    onMoveShouldSetPanResponder:(...args)=>!owner.current.blocked&&(config.onMoveShouldSetPanResponder?.(...args)??false),
    onPanResponderGrant:(...args)=>{owner.current={active:true,blocked:false,last:args};config.onPanResponderGrant?.(...args);},
    onPanResponderMove:(...args)=>{if(!owner.current.active)return;owner.current.last=args;config.onPanResponderMove?.(...args);},
    onPanResponderRelease:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderRelease?.(...args);},
    onPanResponderTerminate:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderTerminate?.(...args);},
  }).panHandlers,[config]);
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}
